 jubin:{name:'Jubin',meaning:'Painted tiles',blurb:'Hand-painted tiles in one colour around a plain panel, like a Peranakan or Portuguese wall.',f:{d:"'Cormorant Garamond', serif",s:"'Pinyon Script', cursive",b:"'Cormorant Garamond', serif"}},
