/* ---------- helpers ---------- */
const SK_AR={kl:1.569,masjid:1.562,pasar:1.625,collyer:1.295,boatquay:1.805,pinang:1.434};
function stitchSvg(lines,color,cell=5){const cv=document.createElement('canvas'),g=cv.getContext('2d'),font='bold 10px Arial, sans-serif',lh=12;g.font=font;
  const w=Math.max(8,...lines.map(l=>Math.ceil(g.measureText(l).width)))+4;cv.width=w;cv.height=lines.length*lh+2;g.font=font;g.textBaseline='top';g.textAlign='center';g.fillStyle='#000';lines.forEach((l,i)=>g.fillText(l,w/2,i*lh+1));
  const d=g.getImageData(0,0,cv.width,cv.height).data;let s='';const k=cell-1.4;
  for(let y=0;y<cv.height;y++)for(let x=0;x<cv.width;x++)if(d[(y*cv.width+x)*4+3]>120)s+=`M${x*cell+.7} ${y*cell+.7}l${k} ${k}M${x*cell+cell-.7} ${y*cell+.7}l${-k} ${k}`;
  return `<svg class="stitch" viewBox="0 0 ${cv.width*cell} ${cv.height*cell}"><path d="${s}" stroke="${color}" stroke-width="${cell*.34}" stroke-linecap="round" fill="none"/></svg>`}
const MOTIF=['...r.r.r...','..rrrrrrr..','.rrryyyrrr.','..rrryrrr..','...rrrrr...','.....g.....','.gg..g..gg.','..ggggggg..','.....g.....'];
function motifSvg(cols,cell=5){let s='';MOTIF.forEach((row,y)=>[...row].forEach((ch,x)=>{if(ch!=='.')s+=`<path d="M${x*cell+.7} ${y*cell+.7}l${cell-1.4} ${cell-1.4}M${x*cell+cell-.7} ${y*cell+.7}l${-(cell-1.4)} ${cell-1.4}" stroke="${cols[ch]}"/>`}));
  return `<svg viewBox="0 0 ${11*cell} ${9*cell}" style="width:22%;height:auto" stroke-width="${cell*.34}" stroke-linecap="round">${s}</svg>`}
function heartRow(color,n=14,cell=4){const H=['.x.x.','xxxxx','.xxx.','..x..'];let s='';for(let i=0;i<n;i++)H.forEach((row,y)=>[...row].forEach((ch,x)=>{if(ch==='x'){const X=(i*7+x)*cell,Y=y*cell;s+=`M${X+.6} ${Y+.6}l${cell-1.2} ${cell-1.2}M${X+cell-.6} ${Y+.6}l${-(cell-1.2)} ${cell-1.2}`}}));
  return `<svg viewBox="0 0 ${n*7*cell} ${4*cell}" style="width:92%;height:auto"><path d="${s}" stroke="${color}" stroke-width="${cell*.34}" stroke-linecap="round"/></svg>`}
function gateSvg(col){let s='';for(let x=6;x<48;x+=7)s+=`<path d="M${x} 148V24"/><path d="M${x-2} 26L${x} 18L${x+2} 26Z" fill="${col}"/>`;
  return `<svg viewBox="0 0 50 150" preserveAspectRatio="none" fill="none" stroke="${col}" stroke-width="2" style="vector-effect:non-scaling-stroke">${s}<path d="M1.5 148V12Q25 0 48.5 12V148Z" stroke-width="3"/><path d="M1 62H49M1 104H49M1 144H49"/><path d="M10 62c0 12 15 10 15 22M40 62c0 12-15 10-15 22"/><circle cx="25" cy="84" r="9"/><circle cx="25" cy="84" r="3.5" fill="${col}"/><circle cx="12" cy="124" r="6"/><circle cx="38" cy="124" r="6"/><path d="M12 30c8 0 13 8 13 16M38 30c-8 0-13 8-13 16"/></svg>`}
const tileUri=(ink,paper)=>svgUriSq(`<svg ${NS} width="64" height="64" viewBox="0 0 64 64"><rect width="64" height="64" fill="${paper}"/><g fill="${ink}"><circle cx="32" cy="32" r="5.5"/>${[0,90,180,270].map(a=>`<ellipse cx="32" cy="19" rx="4.6" ry="9" transform="rotate(${a} 32 32)"/>`).join('')}${[45,135,225,315].map(a=>`<ellipse cx="32" cy="16" rx="2.6" ry="6" transform="rotate(${a} 32 32)" opacity=".8"/>`).join('')}</g><g fill="none" stroke="${ink}" stroke-width="2.4">${[[0,0],[64,0],[0,64],[64,64]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="13"/>`).join('')}</g><g fill="${ink}">${[[0,0],[64,0],[0,64],[64,64]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="5"/>`).join('')}</g><rect x=".5" y=".5" width="63" height="63" fill="none" stroke="${ink}" stroke-opacity=".35"/></svg>`);
const weaveUri=(c1,c2)=>svgUriSq(`<svg ${NS} width="24" height="24" viewBox="0 0 24 24"><defs><linearGradient id="h" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".35"/><stop offset="1" stop-color="#000" stop-opacity=".25"/></linearGradient><linearGradient id="v" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="#fff" stop-opacity=".25"/><stop offset="1" stop-color="#000" stop-opacity=".3"/></linearGradient></defs><rect width="24" height="24" fill="${c1}"/><rect x="0" y="0" width="12" height="12" fill="url(#h)"/><rect x="12" y="0" width="12" height="12" fill="${c2}"/><rect x="12" y="0" width="12" height="12" fill="url(#v)"/><rect x="0" y="12" width="12" height="12" fill="${c2}"/><rect x="0" y="12" width="12" height="12" fill="url(#v)"/><rect x="12" y="12" width="12" height="12" fill="url(#h)"/><path d="M0 12H24M12 0V24" stroke="#000" stroke-opacity=".18"/></svg>`);
const DIA=svgUriSq(`<svg ${NS} width="64" height="64" viewBox="0 0 64 64"><path d="M32 2L62 32L32 62L2 32Z M32 18L46 32L32 46L18 32Z" fill-rule="evenodd"/></svg>`);
const labelSvg=(fill,stroke)=>`<svg viewBox="0 0 300 220"><path d="M34 2H266A32 32 0 0 0 298 34V186A32 32 0 0 0 266 218H34A32 32 0 0 0 2 186V34A32 32 0 0 0 34 2Z" fill="${fill}" stroke="${stroke}" stroke-width="3"/><path d="M40 12H260A28 28 0 0 0 288 40V180A28 28 0 0 0 260 208H40A28 28 0 0 0 12 180V40A28 28 0 0 0 40 12Z" fill="none" stroke="${stroke}" stroke-width="1"/></svg>`;
const ribbonSvg=(fill)=>`<svg viewBox="0 0 300 60"><path d="M0 18H40V54H0L12 36Z" fill="${fill}" opacity=".75"/><path d="M300 18H260V54H300L288 36Z" fill="${fill}" opacity=".75"/><path d="M30 6H270V46H30Z" fill="${fill}"/><path d="M30 46L40 54V46ZM270 46L260 54V46Z" fill="#000" opacity=".35"/></svg>`;
const tagSvg=(fill,stroke)=>`<svg viewBox="0 0 200 300"><path d="M100 -60V18" stroke="#c9b48a" stroke-width="2"/><path fill-rule="evenodd" d="M44 4H156L196 44V296H4V44Z M108 30a8 8 0 1 0 -16 0a8 8 0 1 0 16 0Z" fill="${fill}" stroke="${stroke}" stroke-width="2"/><path d="M48 16H152L184 48V284H16V48Z" fill="none" stroke="${stroke}" stroke-width="1"/></svg>`;
const POSTER_BG={gading:'#f2c14e',nila:'#3a7bc8',marun:'#d2412f',zamrud:'#33a06a',jambu:'#ec7aa0',sage:'#8fb38a',hitam:'#f0e6d2',terakota:'#ec7a40'};

