function wreath(th,n1,n2){const leaves=Array.from({length:12},(_,k)=>{const a=k*30,r=a*Math.PI/180;return `<i class="foil" style="--m:url(${A}eng-${th.eng}.webp);--ar:${ASP[th.eng]};left:${50+Math.cos(r)*36}%;top:${50+Math.sin(r)*36}%;transform:translate(-50%,-50%) rotate(${a+100}deg)"></i>`}).join('');
  return `<div class="wreath reveal">${leaves}<span class="mono foil-text">${esc((n1||'A')[0])}${esc((n2||'A')[0])}</span></div>`}

