const POPPY='M0 0C-11-1-15-13-8-18C-6-23 1-24 3-19C8-23 15-18 12-11C17-6 11 1 0 0Z M-8-18C-3-12-2-6 0 0 M3-19C3-12 2-6 0 0 M12-11C7-7 4-4 0 0';
