      <div class="rm-title"><p class="rm-k">${ev(o,L)}</p><p class="rm-n">${esc(n1)}<i>&amp;</i>${esc(n2)}</p><p class="rm-d">${esc(fmtDate(o.date,o.lang))}</p><i class="rm-tp l"></i><i class="rm-tp r"></i></div>
